401	void ShellController::uninstall()
402	{
403	    m_runtime_timer.Stop();
404	    if (!m_installed)
405	        return;
406	    m_installed = false;
407	    m_agent_pane_collapsed = false;
408	    m_frame->Unbind(wxEVT_DESTROY, &ShellController::on_frame_destroy, this);
409	    m_frame->Unbind(wxEVT_SIZE, &ShellController::on_frame_size, this);
410	    m_tabpanel->Unbind(wxEVT_NOTEBOOK_PAGE_CHANGED, &ShellController::on_notebook_page_changed, this);
411	
412	    m_prepare_canvas_presentation.detach();
413	    m_plater->get_collapse_toolbar().set_enabled(m_saved_collapse_toolbar_enabled);
414	    m_plater->set_sidebar_available(true);
415	    m_plater->set_auto_preview_after_slice(m_saved_auto_preview_after_slice);
416	    m_tabpanel->GetBtnsListCtrl()->Show();
417	
418	    if (m_center_sizer != nullptr) {
419	        if (m_workspace_sizer != nullptr) {
420	            m_workspace_sizer->Detach(m_tabpanel);
421	            if (m_home != nullptr)
422	                m_workspace_sizer->Detach(m_home);
423	        }
424	        if (m_agent_resize_handle != nullptr)
425	            m_center_sizer->Detach(m_agent_resize_handle);
426	        if (m_agent_pane != nullptr)
427	            m_center_sizer->Detach(m_agent_pane);
428	        m_main_sizer->Detach(m_center_sizer);
429	        delete m_center_sizer;
430	        m_center_sizer = nullptr;
431	        m_workspace_sizer = nullptr;
432	    }
433	    if (m_status_row != nullptr)
434	        m_main_sizer->Detach(m_status_row);
435	    if (m_main_sizer->GetItem(m_tabpanel) == nullptr)
436	        m_main_sizer->Add(m_tabpanel, 1, wxEXPAND | wxTOP, 0);
437	
438	    if (m_status_row != nullptr) {
439	        m_status_row->Destroy();
440	        m_status_row = nullptr;
441	    }
442	    if (m_agent_resize_handle != nullptr) {
443	        m_agent_resize_handle->Destroy();
444	        m_agent_resize_handle = nullptr;
445	    }
446	    if (m_agent_pane != nullptr) {
447	        m_agent_pane->Destroy();
448	        m_agent_pane = nullptr;
449	    }
450	    if (m_home != nullptr) {
451	        m_home->Destroy();
452	        m_home = nullptr;
453	    }
454	    // The Notebook is hidden only while Home is up, so the stock presentation
455	    // gets it back shown.
456	    m_tabpanel->Show();
457	    // After the pane (and with it the Agent host) is gone.
458	    m_persistence.reset();
459	    m_workspace.reset();
