1397	void AgentHost::handle_setup_check_key(const std::string& envelope_id, const std::string& payload_json)
1398	{
1399	    cancel_conversation_title();
1400	    if (agent_busy()) {
1401	        send_bridge_error("busy", "Finish or stop the current reply before configuring the Agent.", envelope_id);
1402	        return;
1403	    }
1404	    if (!m_setup) {
1405	        send_bridge_error("setup_unavailable", "This build cannot configure an Agent provider.", envelope_id);
1406	        return;
1407	    }
1408	    const json payload = json::parse(payload_json);
1409	
1410	    SetupCredentials credentials;
1411	    credentials.provider = payload.value("provider", "");
1412	    credentials.api_key  = payload.value("apiKey", "");
1413	    credentials.model    = payload.value("model", "");
1414	    credentials.endpoint = payload.value("endpoint", "");
1415	
1416	    if (credentials.api_key.empty()) {
1417	        send_bridge_error("invalid_payload", "setup_check_key requires an apiKey.", envelope_id);
1418	        return;
1419	    }
1420	    if (m_setup->busy()) {
1421	        send_bridge_error("setup_busy", "A credential check is already running.", envelope_id);
1422	        return;
1423	    }
1424	
1425	    // The pending credentials outlive the request so a verified key can be
1426	    // persisted without the page holding or re-sending the secret.
1427	    m_setup_pending = credentials;
1428	    if (!m_setup->start_check(credentials)) {
1429	        const AgentError error{"unsupported_provider",
1430	                               "This build cannot verify a key for that provider yet.", false};
1431	        send_setup_status("error", envelope_id, std::nullopt, error);
1432	        m_setup_pending.reset();
1433	        return;
1434	    }
1435	    send_setup_status("checking", envelope_id);
1436	}
