1438	void AgentHost::handle_setup_cancel()
1439	{
1440	    if (!m_setup || !m_setup->busy())
1441	        return; // Cancelling a finished check is a benign race.
1442	    m_setup->cancel();
1443	    m_setup_pending.reset();
1444	    send_setup_status("idle");
1445	}
