1447	void AgentHost::pump_setup()
1448	{
1449	    if (!m_setup)
1450	        return;
1451	    std::optional<SetupOutcome> outcome = m_setup->poll();
1452	    if (!outcome)
1453	        return;
1454	
1455	    if (!outcome->ok) {
1456	        send_setup_status("error", {}, outcome->elapsed_ms, outcome->error);
1457	        m_setup_pending.reset();
1458	        return;
1459	    }
1460	
1461	    // The provider answered, so the credentials are good. Persisting them can
1462	    // still fail on a machine with no usable credential store; the Agent works
1463	    // for this session either way, and the user is told which one happened
1464	    // rather than discovering it at the next launch.
1465	    std::string warning;
1466	    if (m_setup_pending && !m_setup->commit(*m_setup_pending))
1467	        warning = "This key could not be saved to the system credential store, so it will have to be entered again "
1468	                  "next time JusPrin starts.";
1469	
1470	    send_setup_status("verified", {}, outcome->elapsed_ms, std::nullopt, warning);
1471	    m_setup_pending.reset();
1472	    // Configuration starts only between turns; messages and retries stay
1473	    // blocked while the credential check is pending.
1474	    set_agent(std::move(outcome->service), AgentAvailability::Ready);
1475	}
