1477	void AgentHost::pump_tools()
1478	{
1479	    // A parked project boundary (Project event delivered before the new
1480	    // directory was in place) resolves here, once per timer tick.
1481	    m_persistence.resolve_pending_boundary();
1482	    if (m_mcp) m_mcp->poll();
1483	    if (m_handshake || m_mcp)
1484	        m_tools.pump();
1485	    // Streaming deltas and progress mark the document dirty without forcing a
1486	    // write each; this pump gives them their throttled flush.
1487	    m_persistence.flush_if_dirty();
1488	}
