34	class RoundedPanel : public wxPanel
35	{
36	public:
37	    RoundedPanel(wxWindow* parent, const wxColour& fill, int radius, const wxSize& size,
38	                 const wxColour& border = wxTransparentColour, wxPenStyle border_style = wxPENSTYLE_SOLID)
39	        : wxPanel(parent, wxID_ANY, wxDefaultPosition, size, wxBORDER_NONE),
40	          m_fill(fill), m_border(border), m_radius(radius), m_border_style(border_style)
41	    {
42	        SetMinSize(size);
43	        // Children inherit this, so a label on the panel sits on its fill
44	        // rather than on the dialog's surface.
45	        SetBackgroundColour(fill);
46	        SetBackgroundStyle(wxBG_STYLE_PAINT);
47	        Bind(wxEVT_PAINT, [this](wxPaintEvent&) {
48	            wxAutoBufferedPaintDC dc(this);
49	            dc.SetBackground(wxBrush(GetParent()->GetBackgroundColour()));
50	            dc.Clear();
51	            dc.SetPen(m_border.IsOk() && m_border.Alpha() != 0
52	                          ? wxPen(m_border, FromDIP(1), m_border_style)
53	                          : *wxTRANSPARENT_PEN);
54	            dc.SetBrush(wxBrush(m_fill));
55	            wxRect bounds = GetClientRect();
56	            bounds.Deflate(FromDIP(1));
57	            dc.DrawRoundedRectangle(bounds, FromDIP(m_radius));
58	        });
59	    }
60	private:
61	    wxColour m_fill;
62	    wxColour m_border;
63	    int m_radius;
