190	void PrinterSetupDialog::rebuild()
191	{
192	    wxWindowUpdateLocker lock(this);
193	    m_description = nullptr;
194	    m_description_is_prompt = false;
195	    m_root->Clear(true);
196	    const auto& metrics = m_theme.metrics();
197	    auto* content = new wxBoxSizer(wxVERTICAL);
198	    build_header(*content);
199	    // States whose content varies (a network printer's details, a list of
200	    // candidates, the no-agent card) take their fitted height.
201	    int target_height = metrics.printer_setup.initial_height;
202	    switch (m_controller->state()) {
203	    case FlowState::Initial:
204	        if (m_agent_connected) {
205	            build_initial(*content);
206	        } else {
207	            target_height = 0;
208	            build_no_agent(*content);
209	        }
210	        break;
211	    case FlowState::Recognizing: build_recognizing(*content); break;
212	    case FlowState::Recognized:
213	        target_height = m_controller->evidence().discovered_device ? 0 : metrics.printer_setup.recognized_height;
214	        build_recognized(*content);
215	        break;
216	    case FlowState::Ambiguous:
217	        target_height = 0;
218	        build_ambiguous(*content);
219	        break;
220	    case FlowState::Error: build_error(*content); break;
221	    case FlowState::Complete: EndModal(wxID_OK); return;
222	    }
223	    m_root->Add(content, 1, wxEXPAND | wxALL, FromDIP(metrics.space_6));
224	    Layout();
225	    Fit();
226	    const int fitted_height = GetClientSize().y;
227	    SetClientSize(wxSize(FromDIP(metrics.printer_setup.dialog_width),
228	                         std::max(FromDIP(target_height), fitted_height)));
229	    CentreOnParent();
230	}
