63	void show_printer_setup(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater)
64	{
65	    // Both entry points, Home and the printer menu, belong to the shell.
66	    ShellController* shell = installed_shell();
67	    if (!shell || !shell->agent_pane())
68	        throw std::logic_error("Add a printer opened without the JusPrin shell installed");
69	
70	    OpenAIPrinterRecognitionConfig config;
71	    if (wxGetApp().app_config) {
72	        const std::string consent = wxGetApp().app_config->get("jusprin_agent", "cloud_consent");
73	        if (consent == "true" || consent == "1")
74	            config.api_key = Agent::load_provider_api_key("openai");
75	        const std::string model = wxGetApp().app_config->get("jusprin_agent", "model");
76	        if (!model.empty()) config.model = model;
77	    }
78	    auto recognition = std::make_unique<OpenAIPrinterRecognition>(std::move(config), Agent::make_openai_http_transport());
79	    auto apply = [&plater](const PrinterCandidate& candidate, std::string& error) {
80	        return SetupCommands::install_and_select_printer(plater, candidate.vendor_id, candidate.model_id,
81	                                                         candidate.variant, candidate.default_material, error);
82	    };
83	    auto controller = std::make_unique<PrinterSetupController>(PrinterCatalog::load(Slic3r::resources_dir()),
84	                                                                std::move(recognition), std::move(apply));
85	    // The same answer the Agent panel gives when it shows its empty state.
86	    const bool agent_connected =
87	        shell->agent_pane()->web_view().host().availability() == Agent::AgentAvailability::Ready;
88	    auto connect = [](const DiscoveredPrinter& printer, const std::string& code, wxString& error) {
89	        return SetupCommands::set_printer_access_code(printer.stable_id, code, error);
90	    };
91	
92	    ModalScrim scrim(owner, theme.palette(dark), theme.metrics().printer_setup.scrim_alpha);
93	    PrinterSetupDialog dialog(scrim.owner_or(owner), theme, dark, std::move(controller), discover_printers(),
94	                              agent_connected, [shell] { shell->open_agent_setup(); }, connect);
95	    dialog.ShowModal();
96	}
